{
  "nl": {
    "issue": [
      {
        "text": "哪些民事法律行为可以通过代理人实施，哪些不得代理",
        "rules": ["c161-1", "c161-2", "c161-doc-personal"]
      },
      {
        "text": "代理的类型（委托代理、法定代理）及代理权的行使依据",
        "rules": ["c163-entrusted", "c163-statutory"]
      },
      {
        "text": "代理人不履行职责、与相对人恶意串通时的民事责任",
        "rules": ["c164-1", "c164-2"]
      },
      {
        "text": "被代理人死亡（法人、非法人组织终止）后，委托代理人实施的代理行为是否有效",
        "rules": ["c174-1", "c174-2"]
      }
    ],
    "conditions": [
      {
        "text": "民事主体（自然人、法人、非法人组织）实施民事法律行为",
        "rules": ["c161-1"]
      },
      {
        "text": "依法律规定、当事人约定或者民事法律行为的性质，应当由本人亲自实施",
        "rules": ["c161-2", "c161-doc-personal"]
      },
      {
        "text": "代理人为委托代理人（依委托取得代理权）或法定代理人（依法律规定取得代理权）",
        "rules": ["c163-entrusted", "c163-statutory"]
      },
      {
        "text": "代理人不履行或者不完全履行职责，并造成被代理人损害",
        "rules": ["c164-1"]
      },
      {
        "text": "代理人与相对人恶意串通，损害被代理人合法权益",
        "rules": ["c164-2"]
      },
      {
        "text": "被代理人死亡后，存在第174条第1款四项情形之一：代理人不知且不应知死亡；继承人承认；授权明确代理权于代理事务完成时终止；死亡前已实施并为继承人利益继续代理",
        "rules": ["c174-1"]
      },
      {
        "text": "作为被代理人的法人、非法人组织终止，参照适用第174条第1款",
        "rules": ["c174-2"]
      }
    ],
    "exceptions": [
      {
        "text": "依法律规定、当事人约定或者行为性质应由本人亲自实施的民事法律行为（立遗嘱、婚姻登记、收养子女等具有人身性质的行为，演出、讲课等须亲自为之的行为）不得代理",
        "rules": ["c161-2", "c161-doc-personal"]
      },
      {
        "text": "被代理人死亡后，不具备第174条第1款四项情形之一的，委托代理行为不因该条而有效",
        "rules": ["c174-1"]
      }
    ],
    "effects": [
      {
        "text": "民事主体可以通过代理人实施民事法律行为",
        "rules": ["c161-1"]
      },
      {
        "text": "委托代理人按照被代理人的委托行使代理权；法定代理人依照法律的规定行使代理权",
        "rules": ["c163-entrusted", "c163-statutory"]
      },
      {
        "text": "代理人不履行或者不完全履行职责造成被代理人损害的，应当向被代理人承担民事责任",
        "rules": ["c164-1"]
      },
      {
        "text": "代理人和相对人恶意串通损害被代理人合法权益的，代理人和相对人承担连带责任",
        "rules": ["c164-2"]
      },
      {
        "text": "被代理人死亡（法人、非法人组织终止）后具备法定情形的，委托代理人实施的代理行为有效",
        "rules": ["c174-1", "c174-2"]
      }
    ],
    "priority": [
      {
        "text": "第161条第2款（不得代理）优先于第161条第1款（可以通过代理人实施）",
        "rules": ["c161-2"]
      },
      {
        "text": "第164条第2款恶意串通的连带责任优先于第164条第1款代理人单独承担民事责任的一般规则",
        "rules": ["c164-2"]
      },
      {
        "text": "符合第174条第1款情形的，代理行为有效，不受被代理人死亡的影响",
        "rules": ["c174-1"]
      }
    ],
    "distinguish": [
      {
        "text": "第163条第1款将代理分为委托代理与法定代理，属分类性规定，未另设行为规则",
        "rules": []
      },
      {
        "text": "代理主要是实施民事法律行为；事实行为（代人算账、代人抄写）不产生对外法律效力，不构成代理",
        "rules": ["c161-doc-fact"]
      },
      {
        "text": "代理是三方（被代理人、代理人、相对人）外部关系，委托合同仅为内部关系；代理人有独立意思表示，中介人仅报告订约机会或充当媒介，不得代委托人签订合同",
        "rules": []
      },
      {
        "text": "直接代理以被代理人名义，间接代理以代理人自己名义，法律后果均直接或间接由被代理人承受；无代理权属无权代理，不发生代理效果，须经追认",
        "rules": []
      }
    ]
  },
